import{_ as a,o,c as t,a0 as s}from"./chunks/framework.CNDWyMYS.js";const k=JSON.parse('{"title":"luarocks make","description":"","frontmatter":{},"headers":[],"relativePath":"luarocks_make.md","filePath":"luarocks_make.md"}'),r={name:"luarocks_make.md"};function c(i,e,n,l,d,u){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="luarocks-make" tabindex="-1">luarocks make <a class="header-anchor" href="#luarocks-make" aria-label="Permalink to &quot;luarocks make&quot;">​</a></h1><p>Compile package in current directory using a rockspec.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p><code>luarocks make [--pack-binary-rock] [&lt;rockspec&gt;]</code></p><p>Builds sources in the current directory, but unlike <a href="./luarocks_build.html">luarocks build</a>, it does not fetch sources, etc., assuming everything is available in the current directory. After the build is complete, it also installs the rock.</p><p>If no argument is given, it looks for a rockspec in the current directory and in <code>./rockspec</code> and <code>./rockspecs</code> subdirectories. Of all the rockspecs the one with the highest version is used. If rockspecs for more than one rock are found, you must specify which one to use through the command-line.</p><p>If <code>--pack-binary-rock</code> is passed, the rock is not installed; instead, a <code>.rock</code> file with the contents of compilation is produced in the current directory.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>luarocks make</span></span></code></pre></div>',9)])])}const h=a(r,[["render",c]]);export{k as __pageData,h as default};
